import { isBlankStrict } from "./empty";
import type { SourceProfile } from "./adapter-types";
import type { AnalysisResult, DiffRecord } from "./types";

/**
 * Advisory corroboration: does text the candidate run still has agree with the
 * reference value a backfill would write?
 *
 * AGENTS.md rule 5 governs this module. Nothing here is matching, recovery, or
 * policy: it produces a *review signal* and nothing else. It never changes a
 * decision lane, never decides, never touches an artifact. The output is
 * evidence quoted back to a person, who remains the one who judges.
 *
 * Why it exists: when a field is wiped across every record, 499 backfills look
 * identical. They are not. The candidate's surviving Description often still
 * states the submission deadline, and where that disagrees with the reference
 * DueDate one of the two is stale — which is a thing to read, not a thing to
 * average away.
 *
 * The signal deliberately does NOT adjudicate. On the shipped pair the
 * reference is usually the later date (a deadline extension, so the text is
 * stale), but at least one record is the reverse. Naming a winner would be a
 * guess wearing a verdict's clothes.
 */

export type CorroborationVerdict =
  /** Surviving text states this value. */
  | "corroborated"
  /** Surviving text states a value of this kind, and it is a different one. */
  | "not_corroborated"
  /** No comparable statement in the text; the signal says nothing. */
  | "no_signal";

export type CorroborationEvidence = {
  /** The matched text, verbatim. */
  matched: string;
  /** Enough surrounding text to judge what the date refers to. */
  quote: string;
  /** Which candidate field the quote came from. */
  sourceField: string;
};

export type CellCorroboration = {
  field: string;
  verdict: CorroborationVerdict;
  evidence: CorroborationEvidence[];
};

export type FieldCorroboration = {
  field: string;
  corroborated: number;
  notCorroborated: number;
  /** corroborated / (corroborated + notCorroborated); null with no sample. */
  agreementRate: number | null;
  /**
   * Whether the run shows the text actually discusses THIS field.
   *
   * Self-calibrating on purpose. On the shipped pair the surviving text agrees
   * with DueDate 89% of the time it states a deadline at all, and with
   * PublishedDate/AwardDate about 2% — the text simply is not about those
   * fields, so "not corroborated" there would mean "the text discussed
   * something else", flagging 44% of records for nothing. A field earns the
   * signal from the data or does not get it.
   */
  trustworthy: boolean;
};

export type CorroborationReport = {
  /** Per-field calibration, for every field a verdict was attempted on. */
  fields: FieldCorroboration[];
  /** Verdicts keyed by `${recordId}�${field}`; only trustworthy fields. */
  cells: Map<string, CellCorroboration>;
  /** True when the profile configures no text fields to read. */
  unconfigured: boolean;
};

const MONTHS: Record<string, number> = {};
[
  "january",
  "february",
  "march",
  "april",
  "may",
  "june",
  "july",
  "august",
  "september",
  "october",
  "november",
  "december"
].forEach((name, index) => {
  MONTHS[name] = index + 1;
  MONTHS[name.slice(0, 3)] = index + 1;
});

const NUMERIC_DATE = /(\d{1,2})\/(\d{1,2})\/(\d{4})/g;
const NAMED_DATE = /([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?\b/g;

/** Month and day only: the year is often absent or wrong in prose. */
type DatePoint = { month: number; day: number };

type FoundDate = DatePoint & { at: number; matched: string };

function findDates(text: string): FoundDate[] {
  const found: FoundDate[] = [];
  for (const match of text.matchAll(NUMERIC_DATE)) {
    found.push({
      month: Number(match[1]),
      day: Number(match[2]),
      at: match.index ?? 0,
      matched: match[0]
    });
  }
  for (const match of text.matchAll(NAMED_DATE)) {
    const month = MONTHS[match[1]!.toLowerCase()];
    if (month === undefined) continue;
    found.push({ month, day: Number(match[2]), at: match.index ?? 0, matched: match[0] });
  }
  return found;
}

/** The reference value's own date, when it reads as one. */
export function parseDatePoint(value: unknown): DatePoint | null {
  const match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(String(value ?? "").trim());
  return match ? { month: Number(match[1]), day: Number(match[2]) } : null;
}

const CUE_WINDOW = 90;
const QUOTE_BEFORE = 100;
const QUOTE_AFTER = 60;

/**
 * Only dates a deadline cue introduces count.
 *
 * Measured on the shipped pair: without this, a pre-bid walkthrough date and a
 * work-completion date were flagged as deadline disagreements. Requiring a cue
 * removed both while keeping every genuine one.
 */
function precededByCue(text: string, at: number, cues: string[]): boolean {
  const before = text.slice(Math.max(0, at - CUE_WINDOW), at).toLowerCase();
  return cues.some((cue) => before.includes(cue));
}

function quoteAround(text: string, at: number): string {
  const start = Math.max(0, at - QUOTE_BEFORE);
  const end = Math.min(text.length, at + QUOTE_AFTER);
  return `${start > 0 ? "…" : ""}${text.slice(start, end).replace(/\s+/g, " ").trim()}${end < text.length ? "…" : ""}`;
}

/** The signal only earns per-cell display above this agreement rate. */
export const TRUSTWORTHY_AGREEMENT_RATE = 0.5;
/** …and only with enough of a sample for the rate to mean anything. */
export const TRUSTWORTHY_MINIMUM_SAMPLE = 10;

export function corroborationKey(recordId: string, field: string): string {
  return `${recordId}�${field}`;
}

/** Candidate-side body: the surviving text is the candidate's. */
function candidateBody(record: DiffRecord): Record<string, unknown> | undefined {
  return record.status === "removed" ? undefined : record.latest;
}

function referenceValueOf(record: DiffRecord, field: string): unknown {
  if (record.status === "added") return undefined;
  const change = record.changedFields.find((entry) => entry.path === field);
  if (change) return change.baselineValue;
  if (record.status === "removed") return record.baseline?.[field];
  return record.latest?.[field];
}

/**
 * Compare every backfillable date-shaped cell against the candidate's surviving
 * text, then keep only the fields the run shows the text actually discusses.
 *
 * O(records × textFields) for extraction — the dates are found once per record
 * and reused across fields — plus O(records × dateFields) for comparison.
 */
export function buildCorroborationReport(
  analysis: AnalysisResult,
  profile: SourceProfile | null
): CorroborationReport {
  const config = profile?.corroboration;
  const textFields = config?.textFields ?? [];
  const cues = (config?.deadlineCues ?? []).map((cue) => cue.toLowerCase());

  if (!profile || textFields.length === 0 || cues.length === 0) {
    return { fields: [], cells: new Map(), unconfigured: true };
  }

  const tallies = new Map<string, { corroborated: number; notCorroborated: number }>();
  const pending: Array<{ key: string; field: string; value: CellCorroboration }> = [];

  for (const record of Object.values(analysis.recordsById)) {
    const body = candidateBody(record);
    if (!body) continue;

    // Extract once per record, not once per field.
    const dated: Array<FoundDate & { sourceField: string; text: string }> = [];
    for (const textField of textFields) {
      const text = body[textField];
      if (typeof text !== "string" || text.length === 0) continue;
      for (const hit of findDates(text)) {
        if (!precededByCue(text, hit.at, cues)) continue;
        dated.push({ ...hit, sourceField: textField, text });
      }
    }
    if (dated.length === 0) continue;

    for (const stat of analysis.fieldStats) {
      const field = stat.field;
      if (textFields.includes(field)) continue;
      // Only cells a backfill would actually write: candidate blank, reference
      // holding a date. Anything else has nothing to corroborate.
      const candidate = body[field];
      if (!isBlankStrict(candidate)) continue;
      const referencePoint = parseDatePoint(referenceValueOf(record, field));
      if (!referencePoint) continue;

      const agrees = dated.some((hit) => hit.month === referencePoint.month && hit.day === referencePoint.day);
      const evidence: CorroborationEvidence[] = dated
        .filter((hit) => agrees === (hit.month === referencePoint.month && hit.day === referencePoint.day))
        .slice(0, 3)
        .map((hit) => ({
          matched: hit.matched,
          quote: quoteAround(hit.text, hit.at),
          sourceField: hit.sourceField
        }));

      const tally = tallies.get(field) ?? { corroborated: 0, notCorroborated: 0 };
      if (agrees) tally.corroborated += 1;
      else tally.notCorroborated += 1;
      tallies.set(field, tally);

      pending.push({
        key: corroborationKey(record.id, field),
        field,
        value: { field, verdict: agrees ? "corroborated" : "not_corroborated", evidence }
      });
    }
  }

  const fields: FieldCorroboration[] = [...tallies.entries()]
    .map(([field, tally]) => {
      const sample = tally.corroborated + tally.notCorroborated;
      const agreementRate = sample > 0 ? tally.corroborated / sample : null;
      return {
        field,
        corroborated: tally.corroborated,
        notCorroborated: tally.notCorroborated,
        agreementRate,
        trustworthy:
          sample >= TRUSTWORTHY_MINIMUM_SAMPLE &&
          agreementRate !== null &&
          agreementRate >= TRUSTWORTHY_AGREEMENT_RATE
      };
    })
    .sort((left, right) => left.field.localeCompare(right.field));

  const trustworthyFields = new Set(fields.filter((entry) => entry.trustworthy).map((entry) => entry.field));
  const cells = new Map<string, CellCorroboration>();
  for (const entry of pending) {
    if (trustworthyFields.has(entry.field)) cells.set(entry.key, entry.value);
  }

  return { fields, cells, unconfigured: false };
}
